import time
from abc import abstractmethod, ABC

from taf.hw.rf_attenuator.exceptions import AttenuationOutOfBounds, AttenuationDifferentThanExpected

from typing import Union, Optional, TYPE_CHECKING

if TYPE_CHECKING:
    from taf.hw.rf_attenuator.devices.jfw.jfw import LinearFadingScenario


class Attenuator(ABC):
    """
    Attenuator API abstract base class. Parent class for implementation.
    """

    def __enter__(self):
        self.connect()
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        self.disconnect()

    def __del__(self):
        self.disconnect()

    @abstractmethod
    def connect(self, **kwargs):
        """
        Subclasses should put here code required to establish connection with attenuation controller
        allowing to change attenuation on specific RF-port of that device
        """
        raise NotImplementedError

    @abstractmethod
    def disconnect(self, **kwargs):
        """
        Subclasses should put here code required to release connection with attenuation controller
        """
        raise NotImplementedError

    @abstractmethod
    def read_port_attenuation(self, port):
        # type: (int) -> Union[int, float]
        """read attenuation value in db for port"""
        raise NotImplementedError

    def set_port_attenuation(self, port, attenuation_value, confirm=True, confirmation_delay=1):
        # type: (int, Union[str,int,float], Optional[bool], Optional[int]) -> None
        """
        Set attenuation for single RF-port inside rf_attenuator device.

        It is the basic building block for other functionalities of Attenuator class, means
        it works as fallback function - if given rf_attenuator doesn't support setting attenuation
        for multiple RF-ports via single command then we can just loop over this method.

        Value expressed in % (like '10%') means 10% of (max attenuation - min attenuation).
        '0%' means min attenuation; 100% is max attenuation.

        :param port: identification of rf-port specific for given rf_attenuator HW, f.ex. pins number
        :param attenuation_value: value to set in dB or %. It is string like '20dB' or '10%'
        :param confirm: if True then read attenuation from rf_attenuator to confirm that it was correctly set
        :param confirmation_delay: additional wait time before read_port_attenuation
        :return: None
        """
        attenuation_value = self._convert_and_check_attenuation_value(attenuation_value)
        self._set_single_port_decibel_attenuation(port, attenuation_value)
        if confirm is True:
            time.sleep(confirmation_delay)
            attenuation_real_value = self.read_port_attenuation(port)
            if attenuation_real_value != attenuation_value:
                msg = ('Desired port id {} value {} not set on rf_attenuator! '
                       'Output from RA {} = {}'.format(port, attenuation_value, port, attenuation_real_value))
                raise AttenuationDifferentThanExpected(msg)

    def read_ports_attenuation(self, ports):
        # type: (list[int]) -> list[float]
        """read attenuation value in db for ports"""
        return [self.read_port_attenuation(port) for port in ports]

    def set_ports_attenuation(self, ports, attenuation_values, confirm=True, confirmation_delay=1):
        # type: (list[int], list[Union[str,int,float]], Optional[bool], Optional[int]) -> None
        """
        Set attenuation for multiple RF-ports inside rf_attenuator device.

        :param ports: identification of rf-port specific for given rf_attenuator HW, f.ex. pins number
        :param attenuation_values: value to set in dB or %. It is string like '20dB' or '10%'
        :param confirm: if True then read attenuation from rf_attenuator to confirm that it was correctly set
        :param confirmation_delay: additional wait time before read_port_attenuation
        :return: None
        """
        attenuation_values = [self._convert_and_check_attenuation_value(attenuation_value)
                              for attenuation_value in attenuation_values]
        self._set_multiple_ports_decibel_attenuation(ports, attenuation_values)
        if confirm is True:
            time.sleep(confirmation_delay)
            attenuation_real_values = self.read_ports_attenuation(ports)
            if attenuation_real_values != attenuation_values:
                msg = ('Desired port id {} value {} not set on rf_attenuator! '
                       'Output from RA {} = {}')
                msg = msg.format(ports, attenuation_values, ports, attenuation_real_values)
                raise AttenuationDifferentThanExpected(msg)

    def _convert_and_check_attenuation_value(self, attenuation_value):
        # type: (Union[int, float, str]) -> float
        """
        Convert attenuation value delivered by user to format usable by ta_attenuator library.
        :param attenuation_value: value to set in dB or %. It is string like '20dB' or '10%'
        :return: attenuation value converted to value usable by ta_attenuator library e.g. 5 db
        """
        real_att_value = self._convert_attenuation_value_to_db(attenuation_value)
        max_value = self.max_attenuation
        min_value = self.min_attenuation
        if real_att_value > max_value or real_att_value < min_value:
            raise AttenuationOutOfBounds(
                attenuation_value,
                real_att_value,
                min_value,
                max_value,
            )
        return real_att_value

    def _convert_attenuation_value_to_db(self, attenuation_value):
        # type: (Union[int, float, str]) -> float
        if isinstance(attenuation_value, float):
            return attenuation_value
        elif isinstance(attenuation_value, int):
            return float(attenuation_value)
        elif isinstance(attenuation_value, str):
            return self._convert_attenuation_value_string(attenuation_value=attenuation_value)
        else:
            raise ValueError("Attenuation value {} passed in not suitable format.\n".format(attenuation_value)
                             + "Unit (% or db) was not specified.")

    def _convert_attenuation_value_string(self, attenuation_value):
        # type: (str) -> float
        if '%' in attenuation_value:
            num = self._extract_numeric_value(attenuation_value)
            delta = 0.01 * num * (self.max_attenuation - self.min_attenuation)
            return self.min_attenuation + delta
        elif 'db' in attenuation_value or 'dB' in attenuation_value:
            return self._extract_numeric_value(attenuation_value)

    @staticmethod
    def _extract_numeric_value(attenuation_value):
        # type: (str) -> float
        num = attenuation_value.replace('db', '').replace('dB', '').replace('%', '')
        num = float(num)
        return num

    @abstractmethod
    def _set_single_port_decibel_attenuation(self, rf_port_address, attenuation_value_db):
        # type: (int, Union[int, float, str]) -> None
        """
        Set attenuation for single RF-port inside rf_attenuator device.
        It should be implemented by specific rf_attenuator impl.
        :param rf_port_address: identification of rf-port specific for given rf_attenuator HW, e.g., pins number
        :param attenuation_value_db: float or int in db
        """
        raise NotImplementedError

    def _set_multiple_ports_decibel_attenuation(self, rf_port_addresses, attenuation_values_db):
        # type: (list[int], list[Union[int, float, str]]) -> None
        """
        Set attenuation for multiple RF-ports inside rf_attenuator device.

        It should be implemented by specific rf_attenuator impl.

        :param rf_port_addresses: identification of rf-ports specific for given rf_attenuator HW, f.ex. pins number
        :param attenuation_values_db: float or int in db
        """
        raise NotImplementedError

    def set_single_rf_port_max_attenuation(self, rf_port_address):
        # type: (int) -> None
        """
        Set attenuation of given RF-port to maximum value supported by given rf_attenuator device.
        """
        self.set_port_attenuation(port=rf_port_address, attenuation_value="100%")

    def set_single_rf_port_min_attenuation(self, rf_port_address):
        # type: (int) -> None
        """
        Set attenuation of given RF-port to minimum value supported by given rf_attenuator device.
        """
        self.set_port_attenuation(port=rf_port_address, attenuation_value="0%")

    def set_rf_ports_max_attenuation(self, rf_ports_addresses):
        # type: (int) -> None
        """
        Set attenuation of multiple RF-ports to maximum value supported by given rf_attenuator device.
        """
        self.set_rf_ports_attenuation(rf_port_address=rf_ports_addresses, attenuation_value="100%")

    def set_rf_ports_min_attenuation(self, rf_ports_addresses):
        # type: (list[int]) -> None
        """
        Set attenuation of multiple RF-ports to minimum value supported by given rf_attenuator device.
        """
        self.set_rf_ports_attenuation(rf_port_address=rf_ports_addresses, attenuation_value="0%")

    def set_linear_fading_scenario(self, port, start_value, end_value, interval, unit):
        # type: (int, int, int, int, str) -> LinearFadingScenario
        """
        Set an linear fading scenario.

        :return LinearFadingScenario:
        """
        raise NotImplementedError

    def set_ports_fading_attenuation(self, set_fading_scenarios, timeout):
        # type: (list[LinearFadingScenario], int) -> None
        """
        Set ports fading attenuation by scenarios.
        """
        raise NotImplementedError

    def escape_command(self):
        # type: () -> None
        """
        Stop command processing and clear the connections command buffer
        """
        raise NotImplementedError

    @staticmethod
    def _validate_min_attenuation(min_val, min_default):
        min_val = min_val or min_default
        if not isinstance(min_val, (int, float)):
            raise TypeError("Attenuation value must be a single int or float number")
        if min_val < min_default:
            raise ValueError("Attenuation value {} is below the lower bound of {}".format(min_val, min_default))
        return min_val

    @staticmethod
    def _validate_max_attenuation(max_val, max_default):
        max_val = max_val or max_default
        if not isinstance(max_val, (int, float)):
            raise TypeError("Attenuation value must be a single int or float number")
        if max_val > max_default:
            raise ValueError("Attenuation value {} is above the upper bound of {}".format(max_val, max_default))
        return max_val
